<?php
declare(strict_types=1);
require __DIR__ . '/connexion.php';
$sql = 'SELECT c.cinChef, c.nomChef, p.nomPla, COALESCE(AVG(e.note), 0) AS moyenne, COUNT(e.iddeg) AS nbEval, (SELECT COUNT(*) FROM degustateur) AS totalDeg FROM chef c INNER JOIN plat p ON p.codePla = c.codePla LEFT JOIN evaluation e ON e.cinchef = c.cinChef GROUP BY c.cinChef, c.nomChef, p.nomPla ORDER BY moyenne DESC, c.nomChef ASC';
$result = $conx->query($sql);
$best = $result->fetch_assoc();
if ($best) $result->data_seek(0);
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Bilan des évaluations</title><link rel="stylesheet" href="mesStyles.css"><style>.winner{padding:18px 20px;margin:18px 0;background:#eaf4ed;border:1px solid #d2e7d8;border-radius:10px}.winner strong{color:#17643b}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:16px 0}.toolbar button{padding:9px 14px}@media print{body{background:white}.container{width:100%;margin:0;padding:0;border:0;box-shadow:none}.toolbar button,.container>p:last-child{display:none}.winner{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><main class="container"><div class="toolbar"><div><p class="eyebrow">RÉSULTATS DE LA COMPÉTITION</p><h1>Bilan des évaluations</h1></div><button type="button" onclick="window.print()">Imprimer / PDF</button></div>
<?php if ($best): ?><section class="winner"><strong>Meilleure moyenne actuelle</strong><p><b><?= htmlspecialchars((string)$best['nomChef'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></b> — <?= htmlspecialchars((string)$best['nomPla'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></p><p><?= number_format((float)$best['moyenne'], 2, ',', ' ') ?> / 20 · <?= (int)$best['nbEval'] ?> évaluation(s) reçue(s)</p></section><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>Chef</th><th>Plat</th><th>Moyenne / 20</th><th>Évaluations reçues</th><th>État</th></tr></thead><tbody>
<?php while ($row = $result->fetch_assoc()): $complete = (int)$row['totalDeg'] > 0 && (int)$row['nbEval'] === (int)$row['totalDeg']; ?><tr><td><?= htmlspecialchars((string)$row['nomChef'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></td><td><?= htmlspecialchars((string)$row['nomPla'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></td><td><?= number_format((float)$row['moyenne'], 2, ',', ' ') ?></td><td><?= (int)$row['nbEval'] ?> / <?= (int)$row['totalDeg'] ?></td><td><?= $complete ? 'Évaluation terminée' : 'Évaluation en cours' ?></td></tr><?php endwhile; ?>
</tbody></table></div><p><a href="evaluation.html">Retour à l'évaluation</a></p></main></body></html>
